import requests,time,json,re; from urllib.parse import urljoin; base='https://pypi.tuna.tsinghua.edu.cn/simple/lief/'; r=requests.get(base,timeout=15); links=re.findall(r'href="([^"]+)"',r.text); link=next(x.split('#')[0] for x in links if 'lief-1.0.0-cp312-abi3-manylinux_2_28_x86_64.whl' in x); start=time.monotonic(); f=requests.get(urljoin(base,link),stream=True,timeout=15);count=0;
for chunk in f.iter_content(65536):
 count+=len(chunk)
 if count>=262144:break
f.close(); seconds=time.monotonic()-start; print(json.dumps({'wheel_status':f.status_code,'bytes':count,'seconds':round(seconds,3),'kbytes_per_second':round(count/1024/max(seconds,0.001),1)}))
